const VERSION='breachline-v3';
const SHELL=['./','./index.html','./style.css','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./js/main.js','./js/ui.js','./js/engine.js','./js/math.js','./js/maps.js','./js/modes.js','./js/navigation.js','./js/weapons.js','./js/ai.js','./js/input.js','./js/audio.js','./js/save.js','./js/renderer.js','./js/compatibility-renderer.js','./js/geometry.js','./js/shaders.js'];
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(VERSION);for(const path of SHELL){const url=new URL(path,self.registration.scope);const response=await fetch(url,{cache:'reload',credentials:'same-origin'});if(!response.ok||response.redirected||new URL(response.url).origin!==self.location.origin)throw new Error('Game shell unavailable');await cache.put(url,response);}await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('breachline-')&&name!==VERSION)await caches.delete(name);await self.clients.claim();})());});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.pathname.startsWith(new URL(self.registration.scope).pathname))return;
 if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(async()=>await caches.match(new URL('./index.html',self.registration.scope))||Response.error()));return;}
 if(SHELL.some(p=>new URL(p,self.registration.scope).pathname===url.pathname))event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request)));
});
